def clean_text(value):
    if not value:
        return ''
    return str(value).strip()

def first_text(*values):
    for value in values:
        value = clean_text(value)
        if value:
            return value
    return ''

for rec in records.sudo():
    vals = {}

    name = first_text(rec.x_name, rec.x_label_ar, rec.x_key, 'متغير')
    label_ar = first_text(rec.x_label_ar, rec.x_name)

    if name and rec.x_name != name:
        vals['x_name'] = name

    if label_ar and rec.x_label_ar != label_ar:
        vals['x_label_ar'] = label_ar

    if vals:
        rec.write(vals)

